import os

import numpy as np

from mudlab.generic.io.utils import get_case_insensitive_glob
from mudlab.generic.utils import u

from ..base_parser import BaseParser
from .namespace import xrd_parsers
from .xrd_parser_mixin import XRDParserMixin


@xrd_parsers.register_parser()
class ASCParser(XRDParserMixin, BaseParser):
    """
        Plain two-column ASCII *.ASC parser: whitespace-separated
        "2theta  intensity" rows, with no header or metadata. Tolerates
        variable spacing, leading whitespace, scientific notation and a
        decimal comma. Intensities are kept as stored (the format carries no
        counting time, so they cannot be normalised to counts-per-second);
        no goniometer parameters are available either.

        This is distinct from the CSV parser, whose dialect sniffer chokes on
        the irregular whitespace used here.
    """

    description = "ASCII *.ASC"
    extensions = get_case_insensitive_glob("*.ASC")

    @classmethod
    def _parse_header(cls, filename, fp, data_objects=None, close=False):
        try:
            basename = u(os.path.basename(filename))
        except Exception:
            basename = None

        data_objects = cls._adapt_data_object_list(data_objects, num_samples=1)
        data_objects[0].update(filename=basename, name="", data_start=0)

        if close: fp.close()
        return data_objects

    @classmethod
    def _parse_data(cls, filename, fp, data_objects=None, close=False):
        f = fp
        obj = data_objects[0]
        if obj.data is None:
            obj.data = []

        if f is not None:
            f.seek(getattr(obj, "data_start", 0) or 0)
            for line in f:
                s = line.strip().replace(",", ".")
                if not s:
                    continue
                parts = s.split()
                try:
                    x = float(parts[0])
                    y = float(parts[1])
                except (IndexError, ValueError):
                    continue
                obj.data.append([x, y])

        obj.data = np.array(obj.data)

        # Fill in the x-range from the data (needed for the goniometer).
        if len(obj.data):
            obj.twotheta_min = float(obj.data[0, 0])
            obj.twotheta_max = float(obj.data[-1, 0])
            obj.twotheta_count = int(obj.data.shape[0])
            if obj.twotheta_count > 1:
                obj.twotheta_step = (
                    (obj.twotheta_max - obj.twotheta_min) / (obj.twotheta_count - 1))

        if close: f.close()
        return data_objects

    pass # end of class
